import { Component, OnInit, OnDestroy, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { TranslateModule, TranslateService } from '@ngx-translate/core';
import { RouterModule } from '@angular/router';
import { Subscription, filter, distinctUntilChanged } from 'rxjs';
import { ethers } from 'ethers';
import { DeploymentRegistryService, PricingInfo } from '@services/deployment-registry.service';
import { ContractService } from '@services/contract.service';
import { BlockchainConfigService } from '@services/blockchain-config.service';
import { ToastService } from '@services/toast.service';
import { DeploymentPricingComponent } from '@components/deployment-pricing/deployment-pricing.component';
import { ContactInputComponent } from '@components/ui/contact-input/contact-input.component';
import { IconComponent } from '@components/ui/icon/icon.component';
import { DeploymentProgressModalComponent } from '@modals/deployment-progress-modal/deployment-progress-modal.component';
import { ActivityService } from '@core/services/activity.service';
import { generateActivityId } from '@core/models/activity.model';
import { LoggerService } from "@services/logger.service";

/** Minimum number of signers required by the SignerManager contract. */
import { environment } from '@environments/environment';

const MIN_SIGNERS = 3;

/** Maximum number of signers allowed in the form. */
const MAX_SIGNERS = 10;

/** Minimum threshold value (matches contract constraint). */
const MIN_THRESHOLD = 3;

@Component({
    selector: 'app-locker-registry',
    standalone: true,
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [CommonModule, FormsModule, RouterModule, DeploymentPricingComponent, TranslateModule, ContactInputComponent, IconComponent, DeploymentProgressModalComponent],
    templateUrl: './locker-registry.component.html',
    styleUrls: ['./locker-registry.component.css']
})
export class LockerRegistryComponent implements OnInit, OnDestroy {
    isAdmin = environment.isAdmin;

    // ─── Constants exposed to template ────────────────────────────────────────
    readonly minSigners = MIN_SIGNERS;
    readonly maxSigners = MAX_SIGNERS;
    readonly minThreshold = MIN_THRESHOLD;

    // ─── UI State ─────────────────────────────────────────────────────────────
    loading = false;
    deploymentInProgress = false;
    deploymentRecap: any | null = null;
    loadingBalance = false;
    isDeployModalVisible = false;
    deploymentSteps: any[] = [];
    /** True when an incomplete deployment is detected on-chain for the connected user. */
    hasInProgressDeployment = false;

    protected isDestroyed = false;

    // ─── Pricing & Fees ───────────────────────────────────────────────────────
    pricingInfo: PricingInfo | null = null;
    feeEstimate: { tokenAmount: string, tokenSymbol: string, networkFee: string, nativeSymbol: string } | null = null;
    loadingFee = false;

    // ─── Form fields ──────────────────────────────────────────────────────────
    /** Address of the owner of the newly deployed LockerContract. */
    ownerAddress = '';

    /** List of signer addresses (3–10 entries). */
    signers: string[] = ['', '', ''];

    /** Required approvals for admin ops in the deployed locker. */
    threshold = MIN_THRESHOLD;

    /** Address from which the stablecoin payment is made. */
    paymentAddress = '';

    /** Symbol of the selected payment stablecoin. */
    paymentToken = 'USDT';

    /** Human-readable balance of the selected payment token for the payment address. */
    paymentBalance: string | null = null;

    // ─── Payment token options ────────────────────────────────────────────────
    readonly paymentTokens = [
        { symbol: 'USDT', name: 'Tether USD' },
        { symbol: 'USDC', name: 'USD Coin' },
        { symbol: 'DAI', name: 'Dai Stablecoin' }
    ];

    private readonly subs = new Subscription();

    constructor(
        private readonly deploymentRegistry: DeploymentRegistryService,
        private readonly contractService: ContractService,
        private readonly blockchainConfig: BlockchainConfigService,
        private readonly toastService: ToastService,
        private readonly translate: TranslateService,
        private readonly cdr: ChangeDetectorRef,
        private readonly activityService: ActivityService, private logger: LoggerService
    ) { }

    ngOnInit(): void {
        this.logger.debug('[LockerRegistryComponent] initialized');
        this.loadPricingInfo();

        // When the connected account changes (including initial value), auto-fill the payment address.
        this.subs.add(
            this.contractService.account$.pipe(
                filter((a): a is string => !!a),
                distinctUntilChanged()
            ).subscribe(account => {
                this.ownerAddress = account;
                if (!this.paymentAddress) {
                    this.paymentAddress = account;
                    this.cdr.markForCheck();
                }
                // Trigger balance load — chainId may now be ready.
                this.loadTokenBalance();
                // Check if this user has an incomplete deployment on-chain
                this.checkInProgressDeployment(account);
            })
        );

        // When chainId becomes available (after async provider init), load the balance.
        this.subs.add(
            this.contractService.chainId$.pipe(
                filter((id): id is bigint => id !== null),
                distinctUntilChanged()
            ).subscribe(() => {
                if (this.paymentAddress) {
                    this.loadTokenBalance();
                }
            })
        );
    }

    /**
     * Detect if the user has a pending (paid but not fully deployed) session on-chain.
     * Restores signers/threshold from localStorage (pre-payment snapshot) or from
     * already-deployed sub-contracts, then automatically opens the progress modal.
     */
    private async checkInProgressDeployment(account: string): Promise<void> {
        try {
            const canDeploy = await this.deploymentRegistry.checkCanDeploy(account);
            if (!canDeploy) return;

            const progress = await this.deploymentRegistry.getDeploymentProgress(account);
            if (!progress || progress.finalized) return;

            const ZERO = '0x0000000000000000000000000000000000000000';

            // ── Restore form state ────────────────────────────────────────────────
            // Priority 1: On-chain SignerManager (most reliable when available)
            if (progress.signerManager !== ZERO) {
                const [onChainSigners, onChainThreshold] = await Promise.all([
                    this.deploymentRegistry.getSignersFromManager(progress.signerManager),
                    this.deploymentRegistry.getThresholdFromHandler(progress.validationHandler)
                ]);
                if (onChainSigners.length >= 3) {
                    this.signers = onChainSigners;
                    this.threshold = onChainThreshold;
                }
            } else {
                // Priority 2: localStorage snapshot saved just before payment
                this.loadPersistedFormState();
            }

            // ── Build steps from on-chain progress ────────────────────────────────
            const steps = [
                { id: 'fetch', name: 'Fetch Bytecodes', status: 'completed' as const },
                { id: 'priceCalculator', name: 'Price Calculator', status: (progress.priceCalculator !== ZERO ? 'completed' : 'pending') as any, address: progress.priceCalculator !== ZERO ? progress.priceCalculator : undefined },
                { id: 'validationHandler', name: 'Validation Handler', status: (progress.validationHandler !== ZERO ? 'completed' : 'pending') as any, address: progress.validationHandler !== ZERO ? progress.validationHandler : undefined },
                { id: 'lockManager', name: 'Lock Manager', status: (progress.lockManager !== ZERO ? 'completed' : 'pending') as any, address: progress.lockManager !== ZERO ? progress.lockManager : undefined },
                { id: 'signerManager', name: 'Signer Manager', status: (progress.signerManager !== ZERO ? 'completed' : 'pending') as any, address: progress.signerManager !== ZERO ? progress.signerManager : undefined },
                { id: 'vestingManager', name: 'Vesting Manager', status: (progress.vestingManager !== ZERO ? 'completed' : 'pending') as any, address: progress.vestingManager !== ZERO ? progress.vestingManager : undefined },
                { id: 'locker', name: 'Locker Contract', status: (progress.lockerContract !== ZERO ? 'completed' : 'pending') as any, address: progress.lockerContract !== ZERO ? progress.lockerContract : undefined }
            ];

            this.deploymentSteps = steps;
            this.hasInProgressDeployment = true;
            this.cdr.markForCheck();
        } catch (e) {
            // Silently ignore — registry might not be available on this chain
            this.logger.warn('Could not check deployment progress:', e);
        }
    }

    /** Open resume modal and trigger deployment from the last completed step. */
    async openResumeModal(): Promise<void> {
        this.isDeployModalVisible = true;
        this.cdr.markForCheck();
        await this.resumeDeployment();
    }

    /** Resume an interrupted deployment — payment has already been recorded on-chain. */
    private async resumeDeployment(): Promise<void> {
        if (this.signers.length < 3) {
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.FILL_FORM'));
            return;
        }

        this.deploymentInProgress = true;
        this.cdr.markForCheck();

        try {
            const recap = await this.deploymentRegistry.executeFullLockerDeployment(
                this.ownerAddress,
                this.signers,
                this.threshold,
                (steps) => {
                    if (this.isDestroyed) return;
                    this.deploymentSteps = steps;
                    this.cdr.detectChanges();
                }
            );

            if (this.isDestroyed) return;

            if (recap) {
                this.deploymentRecap = recap;
                this.hasInProgressDeployment = false;
                this.clearPersistedFormState();

                const customLockersStr = localStorage.getItem('customLockers');
                const customLockers = customLockersStr ? JSON.parse(customLockersStr) : [];
                const chainId = Number(this.contractService.chainId$.value) || 0;
                customLockers.push({ address: recap.locker, name: 'My New Locker', network: 'Custom', chainId, isActive: true });
                localStorage.setItem('customLockers', JSON.stringify(customLockers));

                await this.contractService.switchLocker(recap.locker, false);

                // Log the CREATE_LOCKER activity so it appears in Activities view
                const activityId = generateActivityId();
                this.activityService.addActivity({
                    id: activityId,
                    timestamp: Date.now(),
                    type: 'CREATE_LOCKER',
                    status: 'success',
                    address: this.paymentAddress || this.contractService.account$.value || '',
                    details: {
                        signers: this.signers,
                        threshold: this.threshold,
                        token: this.paymentToken,
                    },
                    chainId: Number(this.contractService.chainId$.value) || 0,
                    txHash: recap.txHash
                });

                this.resetForm();
            } else {
                this.toastService.error('Resume failed — check console for details.');
            }
        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : 'Unknown error';
            this.toastService.error('Resume failed: ' + msg);
        } finally {
            if (!this.isDestroyed) {
                this.deploymentInProgress = false;
                this.cdr.markForCheck();
            }
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[LockerRegistryComponent] destroyed');
        this.isDestroyed = true;
        this.subs.unsubscribe();
    }

    // ─── Pricing ──────────────────────────────────────────────────────────────

    async loadPricingInfo(): Promise<void> {
        this.loading = true;
        try {
            this.pricingInfo = await this.deploymentRegistry.getPricingInfo();
            await this.loadFeeEstimate();
        } catch {
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.LOAD_PRICING_FAILED'));
        } finally {
            this.loading = false;
            this.cdr.markForCheck();
        }
    }

    async loadFeeEstimate(): Promise<void> {
        this.loadingFee = true;
        this.cdr.markForCheck();
        try {
            this.feeEstimate = await this.deploymentRegistry.estimateDeploymentFees(this.paymentToken);
        } catch {
            this.feeEstimate = null;
        } finally {
            this.loadingFee = false;
            this.cdr.markForCheck();
        }
    }

    // ─── Signer management ────────────────────────────────────────────────────

    canAddSigner(): boolean {
        return this.signers.length < MAX_SIGNERS;
    }

    addSigner(): void {
        if (!this.canAddSigner()) { return; }
        this.signers = [...this.signers, ''];
    }

    removeSigner(index: number): void {
        if (this.signers.length <= MIN_SIGNERS) { return; }
        this.signers = this.signers.filter((_, i) => i !== index);
        // Clamp threshold so it never exceeds the new signer count.
        this.clampThreshold();
    }

    onSignerChange(value: string, index: number): void {
        this.signers = this.signers.map((s, i) => (i === index ? value : s));
    }

    // ─── Threshold ────────────────────────────────────────────────────────────

    onThresholdChange(): void {
        this.clampThreshold();
    }

    private clampThreshold(): void {
        this.threshold = Math.max(MIN_THRESHOLD, Math.min(this.threshold, this.signers.length));
    }

    // ─── Payment address ──────────────────────────────────────────────────────

    /** Fill payment address with the currently connected wallet. */
    fillMe(): void {
        const account = this.contractService.account$.value;
        if (account) {
            this.paymentAddress = account;
            this.loadTokenBalance();
        } else {
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.CONNECT_WALLET'));
        }
    }

    /** Called when the payment address input changes. */
    onPaymentAddressChange(): void {
        if (ethers.isAddress(this.paymentAddress)) {
            this.loadTokenBalance();
        } else {
            this.paymentBalance = null;
            this.cdr.markForCheck();
        }
    }

    /** Called when the payment token selector changes. */
    onPaymentTokenChange(): void {
        this.loadFeeEstimate();
        if (ethers.isAddress(this.paymentAddress)) {
            this.loadTokenBalance();
        }
    }

    /**
     * Fetch the balance of the selected payment token for the current payment address.
     * Ensures blockchain config is loaded before resolving the stablecoin address.
     * Uses contractService ERC20 contract (same provider already used across the app).
     */
    async loadTokenBalance(): Promise<void> {
        if (!ethers.isAddress(this.paymentAddress)) {
            this.paymentBalance = null;
            this.cdr.markForCheck();
            return;
        }

        const chainId = Number(this.contractService.chainId$.value);
        if (!chainId) {
            // chainId not yet available — the chainId$ subscription will retry automatically.
            return;
        }

        // Ensure config is loaded before calling getStablecoins() — otherwise returns [].
        await this.blockchainConfig.loadConfig();

        // stablecoins in blockchain-config.json is a keyed object { USDT: {...}, USDC: {...} }
        // not an array — use direct key access instead of .find()
        const stablecoinsMap = this.blockchainConfig.getStablecoins(chainId) as unknown as
            Record<string, { address: string; decimals: number; lockId: number | null }>;
        const coin = stablecoinsMap[this.paymentToken];

        if (!coin) {
            this.logger.warn(`[LockerRegistry] Stablecoin ${this.paymentToken} not found in config for chainId ${chainId}`);
            this.paymentBalance = null;
            this.cdr.markForCheck();
            return;
        }

        this.loadingBalance = true;
        this.cdr.markForCheck();

        try {
            // Reuse the same ERC20 contract helper used elsewhere in the app.
            const tokenContract = this.contractService.getERC20Contract(coin.address);

            let decimals = coin.decimals;
            try {
                decimals = Number(await tokenContract['decimals']());
            } catch {
                // Fall back to config decimals if the on-chain call fails.
            }

            let balance: bigint;
            try {
                balance = await tokenContract['balanceOf'](this.paymentAddress);
            } catch (balanceErr) {
                this.logger.warn('[LockerRegistry] balanceOf call failed (e.g. contract missing/wrong network), falling back to 0', balanceErr);
                balance = 0n;
            }

            this.paymentBalance = ethers.formatUnits(balance, decimals);
        } catch (err) {
            this.logger.warn('[LockerRegistry] Failed to load config or contract:', err);
            this.paymentBalance = null;
        } finally {
            this.loadingBalance = false;
            this.cdr.markForCheck();
        }
    }

    // ─── Validation ───────────────────────────────────────────────────────────

    hasDuplicateSigners = false;
    debugValidationString = '';

    isFormValid(): boolean {
        const validSigners = this.signers.every(s => ethers.isAddress(s));

        const validOwner = ethers.isAddress(this.ownerAddress);

        const addressSet = new Set(this.signers.filter(s => !!s).map(s => s.toLowerCase()));
        this.hasDuplicateSigners = addressSet.size !== this.signers.filter(s => !!s).length;

        const allSignersValid = this.signers.length >= MIN_SIGNERS
            && this.signers.length <= MAX_SIGNERS
            && validSigners
            && !this.hasDuplicateSigners;

        const thresholdValid = this.threshold >= MIN_THRESHOLD
            && this.threshold <= this.signers.length;

        const paymentValid = ethers.isAddress(this.paymentAddress);

        this.debugValidationString = `owner:${validOwner} sigsValid:${validSigners} sigsLen:${this.signers.length} noDup:${!this.hasDuplicateSigners} thresh:${thresholdValid} pay:${paymentValid} ownerAddr:${this.ownerAddress}`;

        return allSignersValid && thresholdValid && paymentValid && validOwner;
    }

    // ─── Submit ───────────────────────────────────────────────────────────────

    async payForRegistry(): Promise<void> {
        if (!this.isFormValid()) {
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.FILL_FORM'));
            return;
        }

        if (!this.contractService.account$.value) {
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.CONNECT_WALLET'));
            return;
        }

        this.deploymentInProgress = true;
        this.cdr.markForCheck();

        try {
            const account = this.contractService.account$.value!;

            // Check if user already paid but hasn't deployed yet (can happen after failed deploy)
            const alreadyPaid = await this.deploymentRegistry.checkCanDeploy(account);

            let paymentOk = alreadyPaid;
            if (alreadyPaid) {
                this.toastService.info('Payment already registered — proceeding to deployment...');
            } else {
                // Persist form state to localStorage before paying so it can be recovered after a crash
                this.persistFormState();

                paymentOk = await this.deploymentRegistry.payForDeployment(
                    this.paymentToken,
                    this.paymentAddress,
                    this.signers,
                    this.threshold
                );

                if (this.isDestroyed) return;

                if (paymentOk) {
                    this.toastService.success(this.translate.instant('LOCKER_REGISTRY.SUCCESS.PAYMENT_DONE'));
                }
            }

            if (paymentOk) {
                // Open Modal
                this.isDeployModalVisible = true;
                this.cdr.markForCheck();

                // Deploy the 6 contracts
                const recap = await this.deploymentRegistry.executeFullLockerDeployment(
                    this.ownerAddress,
                    this.signers,
                    this.threshold,
                    (steps) => {
                        if (this.isDestroyed) return;
                        this.deploymentSteps = steps;
                        this.cdr.detectChanges();
                    }
                );

                if (this.isDestroyed) return;

                if (recap) {
                    this.deploymentRecap = recap;
                    this.hasInProgressDeployment = false;
                    this.clearPersistedFormState();

                    // Add the new Locker to IndexedDB/localStorage
                    const customLockersStr = localStorage.getItem('customLockers');
                    let customLockers = customLockersStr ? JSON.parse(customLockersStr) : [];

                    const chainId = Number(this.contractService.chainId$.value) || 0;

                    customLockers.push({
                        address: recap.locker,
                        name: 'My New Locker',
                        network: 'Custom',
                        chainId: chainId,
                        isActive: true
                    });

                    localStorage.setItem('customLockers', JSON.stringify(customLockers));

                    // Set as active locker without instantly reloading the page (keep the recap visible!)
                    await this.contractService.switchLocker(recap.locker, false);

                    // Log activity
                    const activityId = generateActivityId();
                    this.activityService.addActivity({
                        id: activityId,
                        timestamp: Date.now(),
                        type: 'CREATE_LOCKER',
                        status: 'success',
                        address: this.paymentAddress,
                        details: {
                            signers: this.signers,
                            threshold: this.threshold,
                            token: this.paymentToken,
                        },
                        chainId: chainId,
                        txHash: recap.txHash
                    });

                    this.resetForm();
                } else {
                    this.toastService.error('Payment succeeded but locker deployment failed.');
                }
            }
        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : 'Unknown error';
            this.toastService.error(this.translate.instant('LOCKER_REGISTRY.ERRORS.PAYMENT_FAILED') + ': ' + msg);
        } finally {
            this.deploymentInProgress = false;
            // The modal handles its own open/close state logic but keep the generic forms flags updated
            this.cdr.markForCheck();
        }
    }

    onCloseDeployModal() {
        this.isDeployModalVisible = false;
        this.cdr.markForCheck();
    }

    private resetForm(): void {
        this.signers = ['', '', ''];
        this.threshold = MIN_THRESHOLD;
        this.paymentAddress = '';
        this.paymentToken = 'USDT';
        this.paymentBalance = null;
        this.hasInProgressDeployment = false;
        this.loadFeeEstimate();
    }

    // ─── LocalStorage persistence ─────────────────────────────────────────────

    /** Key used to store pending deployment form state between sessions. */
    private readonly PENDING_DEPLOY_KEY = 'pendingLockerDeployment';

    /**
     * Snapshot the current form state to localStorage before calling payForDeployment.
     * If the page reloads after payment but before finalization, this data is used to restore
     * the signers/threshold so the user doesn't have to re-fill the form.
     */
    private persistFormState(): void {
        try {
            const snapshot = { ownerAddress: this.ownerAddress, signers: this.signers, threshold: this.threshold, paymentToken: this.paymentToken };
            localStorage.setItem(this.PENDING_DEPLOY_KEY, JSON.stringify(snapshot));
        } catch {
            // Ignore — e.g. localStorage disabled in private mode
        }
    }

    /** Restore signers/threshold from the localStorage snapshot taken before payment. */
    private loadPersistedFormState(): void {
        try {
            const raw = localStorage.getItem(this.PENDING_DEPLOY_KEY);
            if (!raw) return;
            const snapshot = JSON.parse(raw) as { ownerAddress?: string, signers: string[], threshold: number, paymentToken: string };
            if (Array.isArray(snapshot.signers) && snapshot.signers.length >= 3) {
                this.ownerAddress = snapshot.ownerAddress || '';
                this.signers = snapshot.signers;
                this.threshold = snapshot.threshold;
                this.paymentToken = snapshot.paymentToken;
            }
        } catch {
            // Malformed data — safe to ignore
        }
    }

    /** Remove the localStorage snapshot once deployment is finalized. */
    private clearPersistedFormState(): void {
        try {
            localStorage.removeItem(this.PENDING_DEPLOY_KEY);
        } catch {
            // Ignore
        }
    }

    // ─── Helpers ─────────────────────────────────────────────────────────────

    /** trackBy for *ngFor on signers to preserve inputs across mutations. */
    trackByIndex(index: number): number {
        return index;
    }
}
