import { Component, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DeploymentRegistryService } from '@services/deployment-registry.service';
import { LoggerService } from "@services/logger.service";

/**
 * Composant pour afficher le pricing progressif et le compte à rebours early bird
 */
@Component({
    selector: 'app-deployment-pricing',
    standalone: true,
    imports: [CommonModule],
    templateUrl: './deployment-pricing.component.html',
    styleUrls: ['./deployment-pricing.component.scss']
})
export class DeploymentPricingComponent implements OnInit, OnDestroy {

    loading = true;
    isEarlyBird = false;
    remainingSlots = 0;
    deployedCount = 0;
    currentPrice = 0;
    progressPercentage = 0;

    constructor(
        private deploymentRegistry: DeploymentRegistryService, private logger: LoggerService
    ) { }

    ngOnInit() {
        this.logger.debug('[DeploymentPricingComponent] initialized');
        this.loadPricingInfo();

        // Rafraîchir toutes les 30 secondes
        setInterval(() => this.loadPricingInfo(), 30000);
    }

    async loadPricingInfo() {
        try {
            const pricingInfo = await this.deploymentRegistry.getPricingInfo();

            if (!pricingInfo) {
                // DeploymentRegistry not available on this chain
                this.loading = false;
                this.isEarlyBird = false;
                this.currentPrice = 499; // Fallback
                return;
            }

            this.currentPrice = pricingInfo.currentPrice;
            this.remainingSlots = pricingInfo.remainingEarlyBird;
            this.deployedCount = pricingInfo.totalDeployments;
            this.isEarlyBird = pricingInfo.isEarlyBird;

            // Calculer le pourcentage de progression
            if (pricingInfo.earlyBirdLimit > 0) {
                this.progressPercentage = (this.deployedCount / pricingInfo.earlyBirdLimit) * 100;
            }

            this.loading = false;

        } catch (error) {
            this.logger.error('Error loading pricing info:', error);
            // Fallback values
            this.currentPrice = 499;
            this.isEarlyBird = false;
            this.loading = false;
        }
    }

    ngOnDestroy(): void {
        this.logger.debug('[DeploymentPricingComponent] destroyed');
    }
}
