import { Component, Input, Output, EventEmitter, OnInit, OnDestroy } from '@angular/core';
import { CommonModule } from '@angular/common';
import { IconComponent } from '@components/ui/icon/icon.component';
import { TranslateModule } from '@ngx-translate/core';
import { DeploymentStep } from '@services/deployment-registry.service';
import { LoggerService } from "@services/logger.service";

@Component({
    selector: 'app-deployment-progress-modal',
    standalone: true,
    imports: [CommonModule, IconComponent, TranslateModule],
    templateUrl: './deployment-progress-modal.component.html',
    styleUrls: ['./deployment-progress-modal.component.css']
})
export class DeploymentProgressModalComponent implements OnInit, OnDestroy {
    @Input() isVisible = false;
    @Input() steps: DeploymentStep[] = [];
    @Output() close = new EventEmitter<void>();

    get isAllCompleted(): boolean {
        if (!this.steps || this.steps.length === 0) return false;
        return this.steps.every(s => s.status === 'completed');
    }

    get hasError(): boolean {
        if (!this.steps) return false;
        return this.steps.some(s => s.status === 'error');
    }

    onClose() {
        this.close.emit();
    }

    constructor(private logger: LoggerService) {
    }

    ngOnInit(): void {
        this.logger.debug('[DeploymentProgressModalComponent] initialized');
    }

    ngOnDestroy(): void {
        this.logger.debug('[DeploymentProgressModalComponent] destroyed');
    }
}
